import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五百三十三章 睁开智慧的眼睛","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/533第五百三十三章 睁开智慧的眼睛.md","filePath":"meditation/巴利文大藏经/533第五百三十三章 睁开智慧的眼睛.md"}'),_={name:"meditation/巴利文大藏经/533第五百三十三章 睁开智慧的眼睛.md"};function r(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第五百三十三章-睁开智慧的眼睛" tabindex="-1">第五百三十三章 睁开智慧的眼睛 <a class="header-anchor" href="#第五百三十三章-睁开智慧的眼睛" aria-label="Permalink to &quot;第五百三十三章 睁开智慧的眼睛&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部41相应5经/迦摩浮经第一(质多相应/处篇/弟子记说)</p><p>有个时候，迦摩浮尊者住在摩叉止陀山的安婆陀伽林之中，有一天，质多居士来到迦摩浮尊者的住处，他顶礼迦摩浮尊者后就在一旁坐下，迦摩浮尊者对质多居士说：“质多居士，「无所亏，有白色之覆盖；车以一辐而转；见来者无恼乱、无苦，断流无缚。」，这句法语是什么意思呢？”</p><p>质多居士说：“迦摩浮尊者，这句话是世尊说的吗？”</p><p>迦摩浮尊者说：“质多居士，这句话确实是世尊所说的，您知道它是什么意思吗？”</p><p>质多居士说：“迦摩浮尊者，请您稍等片刻，我想想看。”</p><p>质多居士说完话就开始思考，没有过多久，质多居士就对迦摩浮尊者说：“迦摩浮尊者，「无所亏」说的是世尊所制定的各项戒律。</p><p>「有白色之覆盖」说的是证悟解脱的果位，从世间彻底的解脱出来。</p><p>「车以一辐」说的是正念（正念解释，见第四百八十三章）。</p><p>「转」说的是循环往复生起又消失的念想。</p><p>「车」说的是由父母所生，由米粥等等食物滋养长大，随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有，会生病、衰老、死亡，是破散之法、坏灭之法，由四大所构成的物质身体（四大解释，见第八十一章）。</p><p>迦摩浮尊者，贪欲、渴爱是烦恼和痛苦，愤怒是烦恼和痛苦，沉迷愚痴是烦恼和痛苦，烦恼和痛苦已经灭尽的修行人，就如同割断树根，砍成无数小木块，投入大火中焚烧成灰烬，又将灰烬撒入江河中被冲走的多罗树一样，这棵多罗树已经不复存在、消失不见，未来也不可能再继续的生长。这些灭尽烦恼和痛苦的修行人，也不会再继续投生到世间，也不会再继续的生死轮回，他们就被称为「无恼乱、无苦」的人，他们就是不会被烦恼和痛苦扰动、污染、影响的人。</p><p>「来者」说的是已经证悟解脱果位的修行人。</p><p>「流」说的是贪欲、渴爱，灭尽贪欲、渴爱的修行人，他们的烦恼和痛苦就被灭尽了，他们的烦恼和痛苦就不会继续的流动、流转、循环了，就如同江河的水干涸后，就不会继续的流动、流转、循环，也如同割断树根，砍成无数小木块，投入大火中焚烧成灰烬，又将灰烬撒入江河中被冲走的多罗树一样，这棵多罗树已经不复存在、消失不见了，这棵多罗树在未来也不会为了生长、生存循环往复的吸取大地中的养料、水分，也不会循环往复利用阳光来制造各种适合生长、生存的资源和条件了，这棵多罗树生长、生存的循环流转力量已经被切断了。已经灭尽贪欲、渴爱的修行人，他们的烦恼和痛苦也被灭尽了，他们烦恼和痛苦的流动也被切断了，他们的贪欲、渴爱、烦恼、痛苦就如同已经干涸的江河之水那样，不会再继续流转、流动、循环，这就叫做「断流」，简单的说就是：「贪欲、渴爱、烦恼、痛苦已经灭尽，不会继续的生起流动」。</p><p>迦摩浮尊者，贪欲、渴爱是束缚捆绑，愤怒是束缚捆绑，沉迷愚痴是束缚捆绑。烦恼和痛苦已经灭尽的修行人，他们就如同解除了身上的锁链、镣铐，从监狱中释放出来的人一样，他们不会再被贪欲、渴爱，愤怒，沉迷的愚痴等等烦恼和痛苦的锁链、镣铐束缚捆绑，他们不会被烦恼和痛苦的监狱囚禁、关押，他们获得了彻底的解脱，这就叫做「无缚」。</p><p>迦摩浮尊者，这就是世尊所说法语：「无所亏，有白色之覆盖；车以一辐而转；见来者无恼乱、无苦，断流无缚。」的意思。”</p><p>迦摩浮尊者说：“质多居士，您说的非常的好，您已经睁开了智慧的眼睛，您已经完全明白和理解了世尊所说的这句法语的意思，您已经开启了解脱的智慧，我在这里随喜赞叹您解法、说法的无量功德。”</p>',18)]))}const f=t(_,[["render",r]]);export{m as __pageData,f as default};
